// Both commands print a JSON report as the last thing on stdout. Pull those
// out so the execution log reads as a result, not a wall of text.
//
// The report is pretty-printed, so it starts on a line that is just "{".
// Searching for the last brace instead would land inside a nested object.
// Written without backslash escapes on purpose: this code travels through JSON
// and n8n's editor, and every layer is another chance to lose one.
const NEWLINE = String.fromCharCode(10);

const last = (text) => {
  const lines = (text || '').split(NEWLINE).map((l) => l.trim());
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i] !== '{') continue;
    try {
      return JSON.parse(lines.slice(i).join(NEWLINE));
    } catch (_) {
      // Not the report; keep looking further up.
    }
  }
  return null;
};

const scrape = last($('Scrape new launches').first().json.stdout);
const retry = last($('Retry held listings').first().json.stdout);

// If every held listing is still unreachable from here, this host is blocked
// too, and the run is doing nothing useful. Say so loudly.
const blocked =
  retry !== null &&
  retry.held_listings_tried > 0 &&
  retry.unreachable === retry.held_listings_tried;

return [
  {
    json: {
      scrape,
      retry,
      blocked,
      verdict: blocked
        ? 'Product Hunt is blocking this machine too. Check the host, or use the official API.'
        : scrape === null || retry === null
          ? 'A command did not print its report. Open the failing node for its output.'
          : 'ok',
    },
  },
];
